import { stringify } from "yaml";
import { z } from "zod";

import { DocsSourceKindSchema, type DocsSourceKind, type SourceDocumentMeta } from "./document.ts";

/**
 * The front matter of a generated file. `source` is what tells the site and CI that a file is generated, and
 * where to edit it. Everything here is derived from the document, so the same document always gives the same
 * bytes: nothing reads the clock.
 */

export const SyncedFromSchema = z
	.object({
		kind: DocsSourceKindSchema,
		id: z.string().min(1),
		url: z.url().nullable(),
	})
	.strict();
export type SyncedFrom = z.output<typeof SyncedFromSchema>;

/** What a generated file carries beyond the document's own details. */
export interface GeneratedPageFacts {
	readonly source: DocsSourceKind;
	/** The finished cover path or URL, when the document has one. */
	readonly coverImage: string | null;
	/** Used when the writer named no author. */
	readonly defaultAuthor: string;
}

type FrontMatterValue = string | number | readonly string[] | SyncedFrom;

function present(fields: Readonly<Record<string, FrontMatterValue | null>>): Readonly<Record<string, FrontMatterValue>> {
	return Object.fromEntries(Object.entries(fields).flatMap(([key, value]): [string, FrontMatterValue][] => (value === null ? [] : [[key, value]])));
}

/** A complete generated Markdown file. The header comment names where to edit it, and is what a reader of the raw file sees first. */
export function generatedFile(meta: SourceDocumentMeta, facts: GeneratedPageFacts, body: string): string {
	const source: SyncedFrom = { kind: facts.source, id: meta.sourceId, url: meta.sourceUrl };
	const author = meta.author ?? facts.defaultAuthor;
	// Every page's category and three dates: first published and last updated as the writer set them, last edited by the tool's clock.
	const filed = { category: meta.category, date: meta.publishedAt, lastUpdated: meta.lastUpdated, editedAt: meta.editedAt };
	const fields =
		meta.collection === "blog"
			? present({ title: meta.title, description: meta.description, author, ...filed, coverImage: facts.coverImage, source })
			: present({
					title: meta.title,
					description: meta.description,
					order: meta.order,
					author,
					...filed,
					coverImage: facts.coverImage,
					tags: meta.tags,
					source,
				});
	const editAt = meta.sourceUrl ?? `${facts.source} document ${meta.sourceId}`;
	return `---\n${stringify(fields, { lineWidth: 0 })}---\n\n<!-- Generated by the docs sync. Edit it at the source: ${editAt} -->\n\n${body.trim()}\n`;
}
